import { AppHypercube3d } from '../02_Hpyercube/App/utils/AppHypercube3d';

export class Solution {
	public divHost: HTMLDivElement;
	public appHypercube3d: AppHypercube3d;
	constructor(id: string) {
		this.init(id);
	}
	async init(id) {
		this.appHypercube3d = await AppHypercube3d.init(id, true);
	}
	public destroy() {
		this.appHypercube3d.destroy();
	}
}
